import math

n, dk, dv, mask = map(int, input().split())
Q = [list(map(float, input().split())) for _ in range(n)]
K = [list(map(float, input().split())) for _ in range(n)]
V = [list(map(float, input().split())) for _ in range(n)]

def fmt(row):
    return ' '.join(f'{round(x, 4) + 0.0:.4f}' for x in row)

scale = math.sqrt(dk)
weights = []
for i in range(n):
    visible = range(i + 1) if mask else range(n)
    scores = {j: sum(a * b for a, b in zip(Q[i], K[j])) / scale for j in visible}
    top = max(scores.values())
    exps = {j: math.exp(s - top) for j, s in scores.items()}
    total = sum(exps.values())
    weights.append([exps[j] / total if j in exps else 0.0 for j in range(n)])

output = [[sum(weights[i][j] * V[j][c] for j in range(n)) for c in range(dv)] for i in range(n)]

print('weights:')
for row in weights:
    print(fmt(row))
print('output:')
for row in output:
    print(fmt(row))
